 for(auto& o:d.objects){X x=node("object",{{"id",num(o.id)},{"kind",num(int(o.kind))},{"points",plist(o.points)},{"text",o.text},{"color",o.color},{"width",num(o.width)},{"size",num(o.fontSize)},{"font",o.font},{"dash",num(o.dash)},{"head",num(o.head)},{"sourceAtom",num(o.sourceAtom)},{"targetAtom",num(o.targetAtom)},{"sourceBond",num(o.sourceBond)},{"targetBond",num(o.targetBond)},{"sourceBondT",num(o.sourceBondT)},{"targetBondT",num(o.targetBondT)},{"autoRoute",num(o.autoRoute)},{"face",num(o.face)},{"closed",num(o.closed)},{"filled",num(o.filled)},{"image",o.imageHex},{"mime",o.mime},{"centerText",num(o.centerText)},{"cross",num(o.cross.enabled)},{"crossWidth",num(o.cross.width)},{"crossSize",num(o.cross.size)},{"crossColor",o.cross.color}});for(auto& r:o.runs)x.c.push_back(node("run",{{"text",r.text},{"color",r.color},{"font",r.font},{"size",num(r.size)},{"face",num(r.face)}}));root.c.push_back(x);}
 for(auto& r:d.reactions){X x=node("reaction",{{"id",num(r.id)},{"p",point(r.p)},{"spacing",num(r.spacing)},{"slotWidth",num(r.slotWidth)},{"slotHeight",num(r.slotHeight)},{"type",num(r.arrowType)},{"cyclic",num(r.cyclic)},{"unit",r.unit},{"centerLabel",r.centerLabel},{"captionFontSize",num(r.captionFontSize)},{"cycleRadius",num(r.cycleRadius)},{"hiddenArrows",ilist(r.hiddenArrows)},{"textColor",r.textColor},{"wrapColumns",num(r.wrapColumns)},{"vertical",num(r.vertical)},{"rowGap",num(r.rowGap)}});for(auto& l:r.links)x.c.push_back(node("link",{{"from",num(l.from)},{"to",num(l.to)},{"members",ilist(l.members)}}));for(auto p:r.slotGrid)x.c.push_back(node("frame",{{"p",point(p)}}));for(auto& m:r.crosses)x.c.push_back(node("cross",{{"index",num(m.index)},{"enabled",num(m.enabled)},{"width",num(m.width)},{"size",num(m.size)},{"color",m.color}}));for(auto& c:r.captionColors)x.c.push_back(node("captionColor",{{"role",num(c.role)},{"index",num(c.index)},{"color",c.color}}));for(auto& s:r.slots)x.c.push_back(node("slot",{{"label",s.label},{"members",ilist(s.members)},{"energy",s.energy},{"startsRow",num(s.startsRow)}}));for(size_t i=0;i<r.above.size();i++)x.c.push_back(node("step",{{"above",r.above[i]},{"below",i<r.below.size()?r.below[i]:""}}));root.c.push_back(x);}
 for(auto& p:d.plots){X x=node("plot",{{"id",num(p.id)},{"p",point(p.p)},{"width",num(p.width)},{"height",num(p.height)},{"title",p.title},{"unit",p.unit},{"mode",num(p.mode)},{"values",num(p.showValues)},{"xLabel",p.xLabel},{"yLabel",p.yLabel},{"xColor",p.xColor},{"yColor",p.yColor},{"yTickStep",num(p.yTickStep)},{"yMin",p.yMin?num(*p.yMin):""},{"yMax",p.yMax?num(*p.yMax):""},{"axisFontSize",num(p.axisFontSize)},{"tickFontSize",num(p.tickFontSize)},{"valueFontSize",num(p.valueFontSize)},{"energyLabelFontSize",num(p.energyLabelFontSize)},{"axisScale",num(p.axisScale)}});for(auto& stage:p.stages)x.c.push_back(node("mechanismStage",{{"label",stage.label},{"start",num(stage.start)},{"end",num(stage.end)},{"fontSize",num(stage.fontSize)}}));for(auto& s:p.states)x.c.push_back(node("state",{{"label",s.label},{"energy",num(s.energy)},{"above",ilist(s.above)},{"below",ilist(s.below)},{"marker",num(s.marker)}}));for(auto& s:p.series){std::string mask;for(bool bit:s.present)mask+=bit?'1':'0';std::string levelColors,segmentColors;for(auto& c:s.levelColors)levelColors+=(levelColors.empty()?"":" ")+(c.empty()?"auto":c);for(auto& c:s.segmentColors)segmentColors+=(segmentColors.empty()?"":" ")+(c.empty()?"auto":c);std::string v;for(double n:s.values)v+=(v.empty()?"":" ")+num(n);x.c.push_back(node("series",{{"name",s.name},{"color",s.color},{"data",v},{"dash",num(s.dash)},{"width",num(s.width)},{"marker",num(s.marker)},{"markerSize",num(s.markerSize)},{"present",mask},{"levelColors",levelColors},{"segmentColors",segmentColors}}));}root.c.push_back(x);}
